export const meta = {
  "slug": "heroicons-shopping-bag",
  "family": "heroicons",
  "name": "shopping-bag",
  "category": "Commerce",
  "motion": "bounce",
  "component": "createHeroiconsShoppingBagIcon"
};

export function createHeroiconsShoppingBagIcon(root, options = {}) {
  let current = { ...options };
  const render = () => {
    root.innerHTML = renderSetIcon(definition, current);
  };
  render();
  const controller = bindSetIcon(root, definition, () => current);
  return {
    play: controller.play,
    reset: controller.reset,
    destroy: controller.destroy,
    update(next = {}) {
      current = { ...current, ...next };
      render();
    },
    get observed() {
      return controller.observed;
    },
  };
}
